FUNCTION_BLOCK FB_P14
VAR_INPUT
    ipText : STRING(254);
END_VAR
VAR_OUTPUT
    ipValue : UDINT := UDINT#0;
END_VAR
VAR
    firstScan : BOOL := TRUE;
    textLength : INT;
    position : INT;
    character : STRING(1);
    digitPosition : INT;
    segmentCount : INT;
    segmentValue : UDINT;
    assembledValue : UDINT;
    segmentHasDigit : BOOL;
    valid : BOOL;
END_VAR

(*
    需求冲突报告：
    “纯组合逻辑（输入字符串 -> 输出整数）”与 C10 要求的
    “上电当拍输出 0”在首次扫描输入为合法非零地址时存在冲突。
    本实现保留 C10：首次扫描输出 0；后续每次扫描重新完整解析。
    本源码未声称经过编译或逐周期功能验证。

    不额外限制地址为 15 个字符：
    原文未禁止前导零，故在 STRING(254) 容量内按数值校验。
*)

ipValue := UDINT#0;
textLength := LEN(ipText);
segmentCount := 1;
segmentValue := UDINT#0;
assembledValue := UDINT#0;
segmentHasDigit := FALSE;
valid := textLength > 0;

FOR position := 1 TO textLength DO
    IF valid THEN
        character := MID(ipText, 1, position);

        IF character = '.' THEN
            IF (NOT segmentHasDigit) OR (segmentCount >= 4) THEN
                valid := FALSE;
            ELSE
                assembledValue :=
                    assembledValue * UDINT#256 + segmentValue;
                segmentCount := segmentCount + 1;
                segmentValue := UDINT#0;
                segmentHasDigit := FALSE;
            END_IF;
        ELSE
            digitPosition := FIND('0123456789', character);

            IF digitPosition = 0 THEN
                valid := FALSE;
            ELSE
                (* segmentValue 在此运算前不超过 255，避免累积溢出。 *)
                segmentValue :=
                    segmentValue * UDINT#10
                    + INT_TO_UDINT(digitPosition - 1);
                segmentHasDigit := TRUE;

                IF segmentValue > UDINT#255 THEN
                    valid := FALSE;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_FOR;

IF valid AND (segmentCount = 4) AND segmentHasDigit THEN
    (* 前三段最多为 16#FFFFFF；此运算结果不超过 UDINT 上限。 *)
    assembledValue := assembledValue * UDINT#256 + segmentValue;

    IF NOT firstScan THEN
        ipValue := assembledValue;
    END_IF;
END_IF;

firstScan := FALSE;

END_FUNCTION_BLOCK
